// src/pages/notifications/NotificationDetailPage.jsx
import React, { useEffect, useState } from 'react';
import { useLocation, useNavigate, useParams } from 'react-router-dom';
import { fetchNotificationById } from '../../api/NotificationsApi';

function NotificationDetailPage() {
  const { id } = useParams();
  const navigate = useNavigate();
  const location = useLocation();

  const [notification, setNotification] = useState(location.state?.notification || null);
  const [loading, setLoading] = useState(!notification);
  const [error, setError] = useState(null);

  useEffect(() => {
    const run = async () => {
      if (notification) return;
      try {
        setLoading(true);
        setError(null);
        const data = await fetchNotificationById(id);
        setNotification(data);
      } catch (e) {
        setError(e);
      } finally {
        setLoading(false);
      }
    };
    run();
  }, [id, notification]);

  if (loading) {
    return (
      <div className="page-container">
        <h1>알림 상세</h1>
        <p>불러오는 중...</p>
      </div>
    );
  }

  if (!notification) {
    return (
      <div className="page-container">
        <h1>알림 상세</h1>
        <p>
          알림 데이터를 찾을 수 없습니다.
          <br />
          (백엔드에 /alerts/{'{id}'} 가 아직 없으면, 목록에서 클릭 진입을 사용하세요)
        </p>
        {error && <p style={{ color: 'red' }}>오류: {error.message}</p>}
        <button className="btn" onClick={() => navigate('/notifications')}>
          알림 목록으로 돌아가기
        </button>
      </div>
    );
  }

  return (
    <div className="page-container">
      <h1>알림 상세 (ID: {id})</h1>

      <div className="notification-detail-card">
        <p><strong>위험도:</strong> {notification.aiLabel || 'UNKNOWN'}</p>
        <p><strong>이벤트 타입:</strong> {notification.eventType}</p>
        <p><strong>수집 시각:</strong> {notification.collectedAt}</p>
        <p><strong>파일 경로:</strong> {notification.path}</p>
        <p><strong>파일 크기:</strong> {notification.size} bytes</p>
        <p><strong>엔트로피:</strong> {notification.entropy != null ? notification.entropy : '-'}</p>
        <p><strong>SHA-256 해시:</strong> {notification.hash || '-'}</p>
        <p><strong>AI 점수:</strong> {notification.aiScore != null ? notification.aiScore : '-'}</p>

        <p><strong>AI 상세 분석:</strong></p>
        <pre className="notification-detail-text">{notification.aiDetail || '(상세 내용 없음)'}</pre>
      </div>

      <button className="btn" onClick={() => navigate('/notifications')}>
        알림 목록으로 돌아가기
      </button>
    </div>
  );
}

export default NotificationDetailPage;
